async function exists(file) {
  return fs.access(file).then(() => true, error => error.code === 'ENOENT' ? false : Promise.reject(error));
}
function digest(content) {
  return createHash('sha256').update(content).digest('hex');
}
async function filesBelow(directory, relative = '') {
  const entries = await fs.readdir(path.join(directory, relative), { withFileTypes: true });
  const files = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const child = path.posix.join(relative.replaceAll('\\', '/'), entry.name);
    if (entry.isDirectory()) files.push(...await filesBelow(directory, child));
    else if (entry.isFile()) files.push(child);
    else throw new Error(`Unsupported source entry: ${path.join(directory, child)}`);
  }
  return files;
}

for (const name of names) {
  const destination = path.join(destinationRoot, name);
  if (await exists(destination)) throw new Error(`Refusing to overwrite existing destination: ${destination}`);
}

// Stage one: copy the exact dirty source and every support file before adaptation.
for (const name of names) {
  await fs.cp(path.join(sourceRoot, name), path.join(destinationRoot, name), { recursive: true, errorOnExist: true });
}
for (const [relative, expected] of Object.entries(expectedSourceHashes)) {
  const copied = await fs.readFile(path.join(destinationRoot, relative));
  if (digest(copied) !== expected) throw new Error(`Dirty source bytes changed: ${relative}`);
}

// Cross-skill support is private to each consumer; projection never relies on another pack/skill.
