function sourceLines(text) {
  return text.match(/.*(?:\n|$)/g)?.filter(line => line.length > 0) ?? [];
}
async function applyUnifiedPatch(patchText) {
  const patchLines = sourceLines(patchText);
  let index = 0;
  while (index < patchLines.length) {
    if (!patchLines[index].startsWith('diff ')) { index += 1; continue; }
    index += 1;
    if (!patchLines[index]?.startsWith('--- ')) throw new Error('Malformed reviewed patch: missing source header');
    index += 1;
    const destinationHeader = patchLines[index];
    if (!destinationHeader?.startsWith('+++ ')) throw new Error('Malformed reviewed patch: missing destination header');
    const headerPath = destinationHeader.slice(4).split('\t', 1)[0].trim().replaceAll('\\', '/');
    const marker = 'content/skills/';
    const markerIndex = headerPath.indexOf(marker);
    if (markerIndex < 0) throw new Error(`Patch destination escapes skill root: ${headerPath}`);
    const relative = headerPath.slice(markerIndex + marker.length);
    const file = path.join(destinationRoot, relative);
    const original = sourceLines(await fs.readFile(file, 'utf8'));
    const output = [];
    let cursor = 0;
    index += 1;
    while (index < patchLines.length && !patchLines[index].startsWith('diff ')) {
      const header = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(patchLines[index]);
      if (!header) { index += 1; continue; }
      const oldStart = Number(header[1]) - 1;
      if (oldStart < cursor) throw new Error(`Overlapping patch hunks: ${relative}`);
      output.push(...original.slice(cursor, oldStart));
      cursor = oldStart;
      index += 1;
      while (index < patchLines.length && !patchLines[index].startsWith('@@ ') && !patchLines[index].startsWith('diff ')) {
        const line = patchLines[index];
        const operation = line[0];
        const text = line.slice(1);
        if (operation === ' ' || operation === '-') {
          if (original[cursor] !== text) throw new Error(`Reviewed source context changed: ${relative}:${cursor + 1}`);
          if (operation === ' ') output.push(text);
          cursor += 1;
        } else if (operation === '+') {
          output.push(text);
        } else if (!line.startsWith('\ No newline')) {
          throw new Error(`Unsupported patch line for ${relative}`);
        }
        index += 1;
      }
    }
    output.push(...original.slice(cursor));
    await fs.writeFile(file, output.join(''));
  }
}
